#!/usr/bin/env bash
#
# B-31.5 Tier A — full uninterrupted indexing baseline.
#
# Indexes a synthetic fixture (or a user-supplied fixture via TIER + ELAI_SCALE_FIXTURE_ROOT)
# end-to-end and records wall time, peak RSS, batch counts, and per-batch
# p50/p99 latency into metrics/phase_b31_5_tier_a.toml.
#
# Usage:
#   run_tier_a.sh
#   TIER=synthetic ELAI_SCALE_FIXTURE_ROOT=/tmp/scale run_tier_a.sh
#
# When ELAI_SCALE_FIXTURE_ROOT/$TIER doesn't exist yet, the synthetic tier is
# auto-generated by make_synth_fixture.sh 200.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"

TIER="${TIER:-synthetic}"
FIXTURE_ROOT="${ELAI_SCALE_FIXTURE_ROOT:-$REPO_ROOT/target/scale_fixtures}"
FIXTURE="$FIXTURE_ROOT/$TIER"
METRICS_FILE="${METRICS_FILE:-$REPO_ROOT/metrics/phase_b31_5_tier_a.toml}"

mkdir -p "$FIXTURE_ROOT"

# Generate the synthetic fixture if needed.
if [[ "$TIER" == "synthetic" ]] && [[ ! -d "$FIXTURE/src" ]]; then
    echo "run_tier_a: generating synthetic fixture at $FIXTURE" >&2
    bash "$SCRIPT_DIR/make_synth_fixture.sh" 200 "$FIXTURE"
fi

if [[ ! -d "$FIXTURE" ]]; then
    echo "run_tier_a: fixture $FIXTURE does not exist — skipping (set ELAI_SCALE_FIXTURE_ROOT)" >&2
    exit 0
fi

# Pick the elai binary launcher.
if [[ -f "$REPO_ROOT/elai.sh" ]]; then
    ELAI="$REPO_ROOT/elai.sh"
elif [[ -f "$REPO_ROOT/elai.bat" ]]; then
    ELAI="$REPO_ROOT/elai.bat"
else
    echo "run_tier_a: no elai launcher found at $REPO_ROOT/elai.{sh,bat}" >&2
    exit 1
fi

# Time + peak RSS. On Linux use `/usr/bin/time -v`; on macOS/BSD/Windows fall
# back to a wallclock + Python ps_mem fallback if available, else 0.
#
# C-17 (DRIFT-I) — tracing output goes to .tier_a_trace.log via RUST_LOG so
# the per-batch p50/p99 computation downstream has real numbers to parse.
TRACE_LOG="$FIXTURE/.tier_a_trace.log"
: > "$TRACE_LOG"
export RUST_LOG="${RUST_LOG:-info,indexing_service=info}"

START=$(date +%s)
PEAK_RSS_KB=0
if command -v /usr/bin/time >/dev/null 2>&1; then
    /usr/bin/time -v -o "$FIXTURE/.tier_a_time.txt" "$ELAI" index "$FIXTURE" 2>>"$TRACE_LOG" || true
    if grep -q "Maximum resident set size" "$FIXTURE/.tier_a_time.txt"; then
        PEAK_RSS_KB=$(awk '/Maximum resident set size/ {print $NF}' "$FIXTURE/.tier_a_time.txt")
    fi
else
    "$ELAI" index "$FIXTURE" 2>>"$TRACE_LOG" || true
fi
END=$(date +%s)
WALL_SECS=$(( END - START ))

PEAK_RSS_MB=$(( PEAK_RSS_KB / 1024 ))

# C-17 (DRIFT-I) — parse real per-batch p50/p99 from the tracing lines
# emitted by indexing_service.rs at the batch_complete span. Each match is
# of the shape `batch_complete  batch_duration_ms=N` (tracing field
# encoding). Awk extracts the integers, sorts, picks p50/p99. Falls back to
# 0 when no batch_complete lines were captured (RUST_LOG filter excluded
# them, or the run did not exercise the batch loop).
PER_BATCH_P50_MS=0
PER_BATCH_P99_MS=0
if [[ -s "$TRACE_LOG" ]] && grep -qE 'batch_complete' "$TRACE_LOG"; then
    # Extract every integer following `batch_duration_ms=` (or
    # `batch_duration_ms = ` depending on tracing formatter), one per
    # batch_complete line.
    BATCH_MS_VALUES=$(grep -E 'batch_complete' "$TRACE_LOG" \
        | grep -oE 'batch_duration_ms[[:space:]]*=[[:space:]]*[0-9]+' \
        | grep -oE '[0-9]+$' \
        | sort -n)
    COUNT=$(printf '%s\n' "$BATCH_MS_VALUES" | grep -cE '^[0-9]+$' || echo 0)
    if [[ "$COUNT" -gt 0 ]]; then
        # p50: 50th percentile, p99: 99th percentile (ceil-rounded index).
        P50_IDX=$(( (COUNT * 50 + 99) / 100 ))
        P99_IDX=$(( (COUNT * 99 + 99) / 100 ))
        if [[ "$P50_IDX" -lt 1 ]]; then P50_IDX=1; fi
        if [[ "$P99_IDX" -lt 1 ]]; then P99_IDX=1; fi
        if [[ "$P50_IDX" -gt "$COUNT" ]]; then P50_IDX=$COUNT; fi
        if [[ "$P99_IDX" -gt "$COUNT" ]]; then P99_IDX=$COUNT; fi
        PER_BATCH_P50_MS=$(printf '%s\n' "$BATCH_MS_VALUES" | sed -n "${P50_IDX}p")
        PER_BATCH_P99_MS=$(printf '%s\n' "$BATCH_MS_VALUES" | sed -n "${P99_IDX}p")
    fi
fi

# Pull the indexing summary out of metadata.db (DECISION-2 layout).
METADATA_DB="$FIXTURE/.elai_cc/indexes/metadata.db"
DKG_DB="$FIXTURE/.elai_cc/indexes/dkg.db"
BATCHES_TOTAL=0
BATCHES_PROC=0
FINAL_NODES=0
FINAL_CHUNKS=0
if command -v sqlite3 >/dev/null 2>&1 && [[ -f "$METADATA_DB" ]]; then
    BATCHES_TOTAL=$(sqlite3 "$METADATA_DB" \
        "SELECT COALESCE(batches_total, 0) FROM project_metadata LIMIT 1;" 2>/dev/null || echo 0)
    BATCHES_PROC=$(sqlite3 "$METADATA_DB" \
        "SELECT COALESCE(batches_processed, 0) FROM project_metadata LIMIT 1;" 2>/dev/null || echo 0)
fi
if command -v sqlite3 >/dev/null 2>&1 && [[ -f "$DKG_DB" ]]; then
    FINAL_NODES=$(sqlite3 "$DKG_DB" "SELECT COUNT(*) FROM dkg_nodes;" 2>/dev/null || echo 0)
fi

mkdir -p "$(dirname "$METRICS_FILE")"
cat > "$METRICS_FILE" <<EOF
# Generated by scripts/scale_test/run_tier_a.sh — TIER=$TIER fixture=$FIXTURE
# C-17 (DRIFT-I): per_batch_p50_ms/p99 parsed from indexing_service
# batch_complete tracing lines (RUST_LOG=indexing_service=info).
[$TIER]
wall_secs = $WALL_SECS
peak_rss_mb = $PEAK_RSS_MB
batches_total = $BATCHES_TOTAL
batches_checkpointed = $BATCHES_PROC
per_batch_p50_ms = $PER_BATCH_P50_MS
per_batch_p99_ms = $PER_BATCH_P99_MS
final_dkg_nodes = $FINAL_NODES
final_chunk_count = $FINAL_CHUNKS

[provenance]
fixture_path = "$FIXTURE"
script = "run_tier_a.sh"

[c17_followup]
measured_in_phase = "C-20"
production_scale_fixture = "linux-v6.7"
EOF

echo "run_tier_a: wrote $METRICS_FILE" >&2
